  /** define PauseCheck (non-warp context) */
  const U_PauseCheck_nowarp = rt.unit("UI/define PauseCheck (non-warp context)", "PauseCheck", (th, f) => {
    const t = th.target as T;
    for (;;) {
      switch (f.pc) {
      case 0:
        if (!gt(G.v.pause, 0)) { f.pc = 1; continue; }
      case 2:
        if (!eq(G.v.pause, 0)) { f.pc = 2; return Ctl.Yield; }
      case 1:
        return Ctl.Return;
      }
    }
  });

  /** define whip and nae nae %s %s %s (non-warp context) */
  const U_whip_and_nae_nae_nowarp = rt.unit("UI/define whip and nae nae %s %s %s (non-warp context)", "whip and nae nae %s %s %s", (th, f) => {
    const t = th.target as T;
    for (;;) {
      switch (f.pc) {
      case 0:
      case 1:
        if ((eq(Math.round(num(f.a[0])), Math.round(t.xPosition())) && eq(Math.round(num(f.a[1])), Math.round(t.yPosition())))) { f.pc = 2; continue; }
        t.setXY(t.x, t.y + num((num((Math.round(num(f.a[1])) - Math.round(t.yPosition()))) / num(f.a[2]))));
        t.setXY(t.x + num((num((Math.round(num(f.a[0])) - Math.round(t.xPosition()))) / num(f.a[2]))), t.y);
        f.pc = 1; return Ctl.Yield;
      case 2:
        t.setXY(num(f.a[0]), num(f.a[1]));
        return Ctl.Return;
      }
    }
  });

